    /// <summary>
    /// MPJ_12065_RestrictCostchangesOnPOs
    /// find method finds record in METPOCostUpdateExceptionRules
    /// </summary>
    /// <param name = "_ecoResCategoryId">Category</param>    
    /// <param name = "_ecoResCategoryHierarchyId">Category HierarchyId/false</param>
    /// <param name = "_forupdate">true or false </param>
    /// <param name = "_concurrencyModel"> concurrency Model/false</param>
    /// <returns>Returns METPOCostUpdateExceptionRules table</returns>
    static METPOCostUpdateExceptionRules find(EcoResCategoryId _ecoResCategoryId, EcoResCategoryHierarchyId _ecoResCategoryHierarchyId, boolean _forupdate = false, ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METPOCostUpdateExceptionRules metPOCostUpdateExceptionRules;

        metPOCostUpdateExceptionRules.selectForUpdate(_forupdate);
        metPOCostUpdateExceptionRules.concurrencyModel(_concurrencyModel);

        select firstonly metPOCostUpdateExceptionRules
            where metPOCostUpdateExceptionRules.CategoryHierarchy   == _ecoResCategoryHierarchyId &&
                  metPOCostUpdateExceptionRules.Category     == _ecoResCategoryId;
         
        return metPOCostUpdateExceptionRules;
    }

/// <summary>
/// MPJ_12065_RestrictCostchangesOnPOs by chaminda on 21022022
/// This clears the cache object in purchase order lines
/// </summary>
public void delete()
{
    super();
    SysGlobalObjectCache    cache       = new SysGlobalObjectCache();
    GlobalObjectCacheScope  cacheScope  = METConstants::PoRestrictionCache;
    cache.clear(cacheScope);
}

/// <summary>
/// MPJ_12065_RestrictCostchangesOnPOs by chaminda on 21022022
/// This clears the cache object in purchase order lines
/// </summary>
public void insert()
{
    super();
    SysGlobalObjectCache    cache       = new SysGlobalObjectCache();
    GlobalObjectCacheScope  cacheScope  = METConstants::PoRestrictionCache;
    cache.clear(cacheScope);
}

/// <summary>
/// MPJ_25267_POCostUpdateCategoryLabelAndValueLookupSavingChecksIssues
/// </summary>
/// <returns>boolean</returns>
public boolean validateWrite()
{
    boolean ret;

    ret = super();
    if(ret)
    {
        EcoResCategory  ecoResCategory;
        select firstonly RecId from ecoResCategory 
            where ecoResCategory.CategoryHierarchy == this.CategoryHierarchy &&
            ecoResCategory.RecId == this.Category;                
        if(!ecoResCategory.RecId)
        {
            ret=false;
            error("@MET:InvalidCategoryHierarchyAndCategoryCombination");
        }
    }

    return ret;
}

/// <summary>
/// MPJ_12065_RestrictCostchangesOnPOs on 08 AUG 2022 by chaminda
/// </summary>
/// <param name="_itemId"> Get item id</param>
/// <returns>
/// A boolean value
/// </returns>
static NoYes isProductCategoryinExceptionRule(ItemId _itemId)
{
    EcoResProductCategory   ecoResProductCategory;
    boolean                 productCategoryListed;
    EcoResCategory          ecoResCategory;       
    
    InventTable             inventTable;
    
    while select CategoryHierarchy from ecoResProductCategory
        exists join RecId, ParentCategory from ecoResCategory
            where ecoResCategory.RecId == EcoResProductCategory.Category
            exists join RecId from inventTable
                where ecoResProductCategory.Product == inventTable.Product
                    && InventTable.ItemId == _itemId
        
    {
        productCategoryListed = METPOCostUpdateExceptionRules::isProductCategoryListed(ecoResCategory,ecoResProductCategory);
        
    }
    
    return productCategoryListed;
}

    /// <summary>
    /// MPJ_12065_RestrictCostchangesOnPOs on 08 AUG 2022 by chaminda
    /// </summary>
    /// <param name="_itemId"> Get item id</param>
    /// <returns>
    /// A boolean value
    /// </returns>
    static NoYes isProductCategoryListed(EcoResCategory _ecoResCategory, EcoResProductCategory   _ecoResProductCategory)
    {
        boolean productCategoryListed;
        if(METPOCostUpdateExceptionRules::find(_ecoResCategory.RecId,_ecoResProductCategory.CategoryHierarchy))
        {
            return true;            
        }
        else
        {
            EcoResCategoryId        parentCategory;
            parentCategory = _ecoResCategory.ParentCategory;
            while (parentCategory)
            {
                if(METPOCostUpdateExceptionRules::find(parentCategory,_ecoResProductCategory.CategoryHierarchy))
                {
                    productCategoryListed=true;
                    break;
                }
                EcoResCategory  ecoResCategoryParent;
                select firstonly ParentCategory from ecoResCategoryParent
                        where ecoResCategoryParent.RecId == parentCategory;

                parentCategory = ecoResCategoryParent.ParentCategory;
            }
        }
        return productCategoryListed;
    }

    /// <summary>
    /// MPJ_12065_RestrictCostchangesOnPOs on 08 AUG 2022 by chaminda
    /// </summary>
    /// <param name="_itemId"> Get item id </param>
    /// <returns>
    /// A boolean value
    /// </returns>
    static NoYes isProductCategoryDefinedOnPurchLineItem(ItemId _itemId)
    {
        EcoResProductCategory   ecoResProductCategory;
        InventTable             inventTable;

        select firstonly RecId from ecoResProductCategory
            exists join RecId from inventTable
                where ecoResProductCategory.Product == inventTable.Product && InventTable.ItemId == _itemId;
       
        if(ecoResProductCategory.RecId)
        {
            return true;
        }
        else
        {
            return false;
        }
        
    }
